import{_ as e,o as r,c as a,al as o}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"Симулятори, що підтримуються спільнотою","description":"","frontmatter":{},"headers":[],"relativePath":"uk/simulation/community_supported_simulators.md","filePath":"uk/simulation/community_supported_simulators.md"}'),i={name:"uk/simulation/community_supported_simulators.md"};function s(n,t,p,d,l,m){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="симулятори-що-підтримуються-спільнотою" tabindex="-1">Симулятори, що підтримуються спільнотою <a class="header-anchor" href="#симулятори-що-підтримуються-спільнотою" aria-label="Permalink to &quot;Симулятори, що підтримуються спільнотою&quot;">​</a></h1><p>Цей розділ містить інформацію про симуляції, що <em>підтримуються спільнотою</em>.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>These simulators are not maintained, tested, or supported, by the core development team. Вони можуть працювати або не працювати з поточними версіями PX4.</p><p>Дивіться <a href="./../dev_setup/dev_env">Встановлення інструментарію</a> для інформації про середовища та інструменти, що підтримуються основною командою розробників.</p></div><p>Інструменти мають різний рівень підтримки своїми спільнотами (деякі добре підтримують, інші - ні). Питання про ці інструменти повинні порушуватися на <a href="./../contribute/support#forums-and-chat">форумах для обговорення</a></p><table tabindex="0"><thead><tr><th>Симулятор</th><th>Опис</th></tr></thead><tbody><tr><td><a href="./../sim_airsim/README">AirSim</a></td><td><p>Міжплатформовий симулятор який надає фізично та візуально реалістичні симуляції. This simulator is resource intensive, and requires a significantly more powerful computer than the other simulators described here.</p><p><strong>Supported Vehicles:</strong> Iris (MultiRotor model and a configuration for PX4 QuadRotor in the X configuration).</p></td></tr><tr><td><a href="./../sim_flightgear/README">FlightGear</a></td><td><p>Симулятор який надає фізично та візуально реалістичні симуляції. Зокрема він може моделювати багато погодних умов, включаючи грози, сніг, дощ та град, а також може симулювати температурні режими та різні типи атмосферних течій. <a href="./../sim_flightgear/multi_vehicle">Симуляція кількох засобів</a> також підтримується.</p> <p><strong>Рухомі засоби, що підтримуються:</strong> Літак, Автожир, Ровер</p></td></tr><tr><td><a href="./../sim_jmavsim/">JMAVSim</a></td><td><p>A simple multirotor/quad simulator. This was previously part of the PX4 development toolchain but was removed in favour of <a href="./../sim_gazebo_gz/">Gazebo</a>.</p> <p><strong>Supported Vehicles:</strong> Quad</p></td></tr><tr><td><a href="./../sim_jsbsim/README">JSBSim</a></td><td><p>Симулятор, який надає моделі просунутої динаміки польоту. Він може використовуватися для моделювання реалістичної динаміки польоту, заснованої на даних з аеродинамічної труби.</p> <p><strong>Рухомі засоби, що підтримуються:</strong> Літак, Квадрокоптер, Гексакоптер</p></td></tr><tr><td><a href="./../sim_pterosim/">PteroSim</a></td><td><p>Proprietary high-fidelity UAV simulation built on Unreal Engine 5 and JSBSim. Connects to PX4 SITL over the Simulator MAVLink API with lockstep synchronization.</p><p><strong>Supported Vehicles:</strong> Free tier: Multicopter. Paid tiers: Fixed-wing, VTOL, Helicopter.</p></td></tr><tr><td><a href="./../sim_rotorpy/">RotorPy</a></td><td><p>A Python-based multirotor simulation environment with aerodynamic forces and moments, actuator limits, sensor noise, wind, obstacles, and a Gymnasium interface for research workflows.</p><p><strong>Supported Vehicles:</strong> Quad</p></td></tr><tr><td><a href="./../sim_xplane/">X-Plane</a></td><td><p>A commercial flight simulator using blade element theory for flight dynamics. The PX4 integration uses the community-supported px4xplane bridge plugin.</p><p><strong>Preconfigured PX4 targets:</strong> Plane, Multicopter, VTOL. Additional X-Plane aircraft or vehicle models can be integrated when PX4 has a matching SITL-capable control path and px4xplane can map the required actuator outputs to writable X-Plane datarefs.</p></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="./../sim_gazebo_gz/">Gazebo</a> and <a href="./../sim_sih/">SIH</a> are the officially supported simulators. See the <a href="./">Simulation</a> page for more information.</p></div>',6)])])}const h=e(i,[["render",s]]);export{c as __pageData,h as default};
